#include <kin/ecs/render.hpp>
#include <kin/ecs/script.hpp>
#include <kin/platform/input.hpp>
#include <kin/scene/scene_asset.hpp>
#include <kin/scripting/entity_scripts.hpp>
#include <kin/scripting/script_engine.hpp>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <vector>
using Clock = std::chrono::steady_clock;
double ms(Clock::time_point start) { return std::chrono::duration<double,std::milli>(Clock::now()-start).count(); }
template<class F> void samples(const char* name,F fn) {
    std::vector<double> times;
    for(int i=0;i<33;++i) { auto start=Clock::now(); fn(); if(i>=3)times.push_back(ms(start)); }
    std::cout<<name<<" [";for(std::size_t j=0;j<times.size();++j)std::cout<<(j?",":"")<<times[j];std::cout<<"]\n";
}
int main(int argc,char**argv) {
    assert(argc==2);
    const std::filesystem::path root=argv[1]; std::filesystem::create_directories(root);
    std::ofstream(root/"scene.lua") << R"lua(
local entity
function on_load(scene)
    entity=scene:entity('scene_probe')
    entity:set_transform(0,0)
end
function update(ctx)
    assert(ctx.dt>0)
    for i=1,10000 do
        assert(entity:alive())
        entity:translate(1,-1)
    end
end
)lua";
    std::ofstream(root/"entity.lua") << R"lua(
function on_update(self,dt)
    for i=1,100 do
        assert(self:alive())
        local x,y=self:position()
        self:move(1,-1)
        self:set_rotation(self:rotation()+1)
    end
end
)lua";
    samples("scene_vm_create_ms",[&]{kin::ScriptEngine engine;});
    kin::EcsWorld scene_world;kin::register_builtin_editor_components(scene_world);
    kin::ScriptEngine scene;
    assert(scene.load_file(root,"scene.lua"));
    assert(scene.call_on_load({.world=&scene_world,.script_path=root/"scene.lua"}));
    samples("scene_20000_calls_ms",[&]{
        if(!scene.call_update(kin::ScriptFrameContext{.dt=1.f/60})) {
            std::cerr<<scene.last_error()<<'\n';std::abort();
        }
    });
    const auto entity=scene_world.entities().find_by_name("scene_probe");
    assert(entity.get<kin::Transform2D>()->pos.x==330000.f);
    kin::EcsWorld world;kin::register_builtin_editor_components(world);
    for(int i=0;i<100;++i)
        world.entity("entity_probe_"+std::to_string(i)).set(kin::Transform2D{}).set(kin::ScriptComponent{.asset={.id="entity.lua"}});
    kin::EntityScripts scripts{{.content=root,.check_frames=0}};kin::Input input;
    samples("entity_50000_calls_ms",[&]{scripts.update(world,input,1.f/60);});
    const auto actor=world.entities().find_by_name("entity_probe_0");
    assert(actor.get<kin::Transform2D>()->pos.x==3300.f);
    std::cout<<"positions "<<entity.get<kin::Transform2D>()->pos.x<<' '<<actor.get<kin::Transform2D>()->pos.x<<'\n';
}

