#include <kin/scene/scene_asset.hpp>
#include <kin/scripting/workflows2d.hpp>
#include <kin/platform/input.hpp>
#include <sol/sol.hpp>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <filesystem>
#include <iostream>
#include <vector>
using Clock=std::chrono::steady_clock;
template<class F> void measure(const char* name,F fn) {
    std::vector<double> values;
    for(int n=0;n<33;++n) { const auto t=Clock::now();fn();if(n>=3)values.push_back(std::chrono::duration<double,std::milli>(Clock::now()-t).count()); }
    std::cout<<name<<" [";for(std::size_t j=0;j<values.size();++j)std::cout<<(j?",":"")<<values[j];std::cout<<"]\n";
}
int main(int argc,char**argv) {
    assert(argc==2);kin::EcsWorld world;kin::register_builtin_editor_components(world);
    auto services=std::make_shared<kin::ScriptWorkflows2D>(world,argv[1]);
    measure("bind_50_vms_ms",[&]{for(int i=0;i<50;++i){sol::state lua;lua.open_libraries(sol::lib::base);kin::bind_lua_workflows2d(lua,[services]{return services;});}});
    sol::state lua;lua.open_libraries(sol::lib::base,sol::lib::table);kin::bind_lua_workflows2d(lua,[services]{return services;});
    lua.script("input_contexts.push('game','key fire Space\\n')");
    sol::protected_function query=lua.load(R"lua(
local held,pressed,released,axis=input_contexts.held,input_contexts.pressed,input_contexts.released,input_contexts.axis
local count=0
for i=1,100000 do
    assert(not held('game','fire') and not pressed('game','fire') and not released('game','fire'))
    assert(axis('game','move')==0)
    count=count+1
end
return count
)lua");
    measure("input_400000_calls_ms",[&]{auto result=query();if(!result.valid()){sol::error e=result;std::cerr<<e.what()<<'\n';std::abort();}assert(result.get<int>()==100000);});
    sol::protected_function tables=lua.load(R"lua(
local devices,state=controllers.devices,controllers.state
local count=0
for i=1,20000 do
    assert(#devices()==0 and not state(1).connected)
    count=count+1
end
return count
)lua");
    measure("tables_40000_calls_ms",[&]{auto result=tables();if(!result.valid()){sol::error e=result;std::cerr<<e.what()<<'\n';std::abort();}assert(result.get<int>()==20000);});
}
